import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.D9E58p8B.js";const u=JSON.parse('{"title":"Daimon","description":"","frontmatter":{"layout":"home","title":"Daimon","hero":{"name":"Daimon","text":"Eyes and hands for your AI","tagline":"The local organ that gives any AI eyes, hands and an on-screen presence.","image":{"src":"/daimon-icon.svg","alt":"Daimon logo"},"actions":[{"theme":"brand","text":"Get started","link":"/en/guide/installation"},{"theme":"alt","text":"Guide","link":"/en/guide/"},{"theme":"alt","text":"Tool reference","link":"/en/reference/"}]},"features":[{"title":"Vue (Sight)","details":"Screen captures, on-device text location (OCR), display geometry and calibration.","link":"/en/reference/vue","linkText":"The vue_* tools"},{"title":"Touché (Touch)","details":"The accessibility tree of a window, or the element under a point.","link":"/en/reference/touche","linkText":"The touche_* tools"},{"title":"Mains (Hands)","details":"Click, type, press, drag, navigate and drive windows, under a ceiling you set.","link":"/en/reference/mains","linkText":"The main_* tools"},{"title":"Overlay","details":"On-screen markers to follow what the AI does, off by default.","link":"/en/reference/overlay","linkText":"The overlay_* tools"},{"title":"You stay in control","details":"Ceiling L0 to L4, exclusions, secret masking, activity log. An AI can read the ceiling, never raise it.","link":"/en/guide/plafond-et-exclusions","linkText":"The ceiling and exclusions"},{"title":"Local, no account","details":"Daimon calls no AI model, has no account and sends nothing to ArboRithm.","link":"/en/guide/confidentialite","linkText":"Privacy"}]},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md"}'),i={name:"en/index.md"};function l(r,e,s,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h2 id="what-daimon-is" tabindex="-1">What Daimon is <a class="header-anchor" href="#what-daimon-is" aria-label="Permalink to &quot;What Daimon is&quot;">​</a></h2><p>AI assistants reason well but see nothing of your desktop. Daimon is the missing organ: a small resident application that exposes <strong>perception</strong> (the screen, the structure of windows) and <strong>action</strong> (mouse, keyboard, windows) to any AI client that speaks the <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a>.</p><p>Daimon is a tool, not an assistant. It answers when an AI client queries it, never the other way round: it calls no AI model itself.</p><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><ol><li><a href="/Daimon/en/guide/installation.html">Install Daimon</a> on macOS or Windows.</li><li><a href="/Daimon/en/guide/autorisations.html">Grant the permissions</a> (macOS) and <a href="/Daimon/en/guide/clients-mcp.html">register your AI clients</a>.</li><li>Understand the <a href="/Daimon/en/guide/modele-mental.html">mental model</a>: Vue, Touché, Mains, Overlay, Face.</li><li>Set the <a href="/Daimon/en/guide/plafond-et-exclusions.html">Mains ceiling</a> to your liking.</li><li>When in doubt, ask your AI to call <code>daimon_doctor</code>: see <a href="/Daimon/en/guide/depannage.html">troubleshooting</a>.</li></ol><h2 id="platforms" tabindex="-1">Platforms <a class="header-anchor" href="#platforms" aria-label="Permalink to &quot;Platforms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Configuration</th></tr></thead><tbody><tr><td>macOS</td><td>Apple Silicon, macOS 12 or later</td></tr><tr><td>Windows</td><td>Windows 10 version 2004 or later, x64</td></tr><tr><td>Windows (preview)</td><td>Windows 10 version 2004 or later, ARM64</td></tr></tbody></table>',7)])])}const f=t(i,[["render",l]]);export{u as __pageData,f as default};
